<?php declare(strict_types=1); ?>
<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HEX CHEATS SHOP | Catalog Manager</title>
<style>
:root{font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif;color:#182638;background:#f3f6f9;--navy:#142337;--blue:#246bce;--line:#e0e7ee;--muted:#708095;--green:#16845f;--red:#bd3b4b}*{box-sizing:border-box}body{margin:0}.top{height:68px;background:var(--navy);color:white;display:flex;align-items:center;justify-content:space-between;padding:0 max(18px,calc((100% - 1180px)/2))}.brand{display:flex;align-items:center;gap:10px;font-weight:850;letter-spacing:.03em}.mark{width:36px;height:36px;background:#2a4565;border-radius:10px;display:grid;place-items:center;color:#b8d7ff}.actions{display:flex;gap:8px}.wrap{width:min(1180px,calc(100% - 34px));margin:26px auto 55px}.heading{display:flex;justify-content:space-between;align-items:end;gap:15px;margin-bottom:20px}.heading h1{margin:3px 0 0;font-size:26px;letter-spacing:-.04em}.muted{color:var(--muted);font-size:12px}.button{border:1px solid transparent;border-radius:9px;padding:9px 13px;background:var(--blue);color:white;font-size:12px;font-weight:750;cursor:pointer}.button:hover{filter:brightness(.95)}.button.secondary{background:white;border-color:var(--line);color:#384a5d}.button.danger{background:var(--red)}.button:disabled{opacity:.55;cursor:wait}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:13px}.card{background:white;border:1px solid var(--line);border-radius:13px;overflow:hidden;box-shadow:0 5px 20px #19304b08}.thumb{height:125px;background:linear-gradient(135deg,#132337,#2a4964);display:grid;place-items:center;color:#b7d7fa;font-size:32px;font-weight:900}.thumb img{width:100%;height:100%;object-fit:cover}.body{padding:14px}.title{display:flex;justify-content:space-between;gap:8px;align-items:start}.title h2{font-size:14px;margin:0}.pill{padding:4px 7px;border-radius:99px;background:#eef3f8;color:#52647a;font-size:9px;white-space:nowrap}.meta{font:10px ui-monospace,monospace;color:var(--muted);margin-top:6px;word-break:break-all}.prices{font-size:11px;color:#3d4e62;line-height:1.65;margin:12px 0}.row{display:flex;gap:7px;flex-wrap:wrap}.row .button{flex:1}.modal{position:fixed;inset:0;background:#07142688;display:grid;place-items:center;padding:14px;z-index:5}.modal.hidden{display:none}.dialog{width:min(760px,100%);max-height:94vh;overflow:auto;background:white;border-radius:15px;box-shadow:0 20px 70px #0e253744}.dialog-head{display:flex;justify-content:space-between;align-items:center;padding:17px 20px;border-bottom:1px solid var(--line);position:sticky;top:0;background:white;z-index:2}.dialog-head h2{font-size:17px;margin:0}.close{border:0;background:#eef2f5;border-radius:7px;width:30px;height:30px;font-size:17px;cursor:pointer}.dialog-body{padding:19px 20px}.form{display:grid;grid-template-columns:1fr 1fr;gap:12px}.field.full{grid-column:1/-1}.field label{display:block;font-size:10px;font-weight:800;color:#52647a;margin:0 0 5px}.field input,.field textarea,.field select{width:100%;border:1px solid #d8e0e8;border-radius:8px;padding:9px 10px;background:white;color:#182638;font:12px inherit}.field textarea{min-height:112px;resize:vertical;font-family:ui-monospace,monospace;font-size:11px;line-height:1.5}.hint{font-size:10px;color:var(--muted);margin-top:4px}.checks{display:flex;gap:18px;align-items:center;font-size:11px}.checks label{display:flex;align-items:center;gap:6px}.checks input{width:auto}.form-actions{display:flex;justify-content:end;gap:8px;margin-top:15px}.note{background:#fff7df;border:1px solid #f1e3bc;color:#765719;border-radius:8px;padding:10px;font-size:10px;line-height:1.5;margin-bottom:13px}.status{min-height:20px;font-size:11px;color:var(--green);margin-top:10px}.status.error{color:var(--red)}.image-row{display:flex;gap:8px;align-items:center;margin-top:10px}.image-row input{font-size:10px;min-width:0;flex:1}.empty{background:white;border:1px dashed var(--line);border-radius:12px;padding:35px;text-align:center;color:var(--muted)}
@media(max-width:620px){.wrap{width:calc(100% - 22px);margin-top:18px}.heading{align-items:start;flex-direction:column}.form{grid-template-columns:1fr}.field.full{grid-column:auto}.top{padding:0 12px}.actions .button{padding:8px}.dialog-body{padding:14px}}
</style></head>
<body><header class="top"><a class="brand" href="/admin"><span class="mark">HX</span><span>HEX CHEATS SHOP · CATALOG</span></a><div class="actions"><a class="button secondary" href="/admin/homepage">Homepage</a><a class="button secondary" href="/admin/customers">Customers &amp; orders</a><button class="button secondary" id="logout">Sign out</button></div></header>
<main class="wrap"><div class="heading"><div><div class="muted">Products · pricing · images · reseller mappings</div><h1>Catalog control</h1><div class="muted">Changes are written to the shared shop database and appear on the storefront.</div></div><button class="button" id="add">＋ Add product</button></div><div class="note">Product images are stored in the shop database. Upload images you own or have permission to use; each image is limited to 5 MB.</div><div class="grid" id="products"><div class="empty">Loading catalog…</div></div><div class="status" id="status"></div></main>
<div class="modal hidden" id="modal" role="dialog" aria-modal="true"><div class="dialog"><div class="dialog-head"><h2 id="modalTitle">Add product</h2><button class="close" id="close" aria-label="Close">×</button></div><div class="dialog-body"><form id="form"><div class="form">
<div class="field"><label for="key">Product key (slug)</label><input id="key" required pattern="[a-z0-9_-]{2,60}" maxlength="60" placeholder="product_access"><div class="hint">Lowercase letters, numbers, underscores or hyphens.</div></div>
<div class="field"><label for="productId">Reseller product ID</label><input id="productId" required maxlength="80" placeholder="136"></div>
<div class="field"><label for="name">Product name</label><input id="name" required maxlength="120"></div>
<div class="field"><label for="category">Category / game</label><input id="category" maxlength="100" placeholder="Free Fire"></div>
<div class="field"><label for="platform">Platform</label><select id="platform"><option value="">Not specified</option><option>iOS</option><option>Android</option><option>PC</option><option>Windows</option><option>Cross-platform</option><option>Other</option></select></div>
<div class="field"><label for="accessMode">Access type</label><select id="accessMode"><option value="all">Root / non-root</option><option value="root">Root</option><option value="non_root">Non-root</option></select></div>
<div class="field full"><label for="durations">Available durations (one per line)</label><textarea id="durations" required placeholder="1 Day&#10;7 Days"></textarea></div>
<div class="field"><label for="prices">INR prices (duration = amount)</label><textarea id="prices" required placeholder="1 Day = 149&#10;7 Days = 499"></textarea></div>
<div class="field"><label for="usdPrices">USD prices (optional, duration = amount)</label><textarea id="usdPrices" placeholder="1 Day = 2.00"></textarea></div>
<div class="field"><label for="apiDurations">Reseller duration mapping (optional)</label><textarea id="apiDurations" placeholder="1 Day = 1 Days"></textarea></div>
<div class="field"><label for="stock">Stock by duration (optional)</label><textarea id="stock" placeholder="1 Day = 999999"></textarea></div>
<div class="field full"><label for="description">Product description</label><textarea id="description" maxlength="2000" placeholder="What customers should know before choosing a duration."></textarea></div>
<div class="field full"><label for="features">Product features (one per line)</label><textarea id="features" placeholder="Instant digital delivery&#10;Secure checkout"></textarea></div>
<div class="field"><label for="demoUrl">Demo video URL (optional)</label><input id="demoUrl" type="url" maxlength="2048" placeholder="https://…"></div>
<div class="field"><label for="downloadUrl">Product download URL (optional)</label><input id="downloadUrl" type="url" maxlength="2048" placeholder="https://…"></div>
<div class="field"><label for="sortOrder">Display order</label><input id="sortOrder" type="number" min="0" max="100000" value="0"></div>
<div class="field"><label for="soldCount">Sold-count display</label><input id="soldCount" type="number" min="0" max="1000000000" value="0"><div class="hint">Set 0 to hide the count; this is display text, not a payment/order total.</div></div>
<div class="field"><label for="image">Product image</label><input id="image" type="file" accept="image/png,image/jpeg,image/webp"><div class="hint">PNG, JPEG or WebP · maximum 5 MB.</div></div>
<div class="field full checks"><label><input id="enabled" type="checkbox" checked> Visible on storefront</label><label><input id="maintenance" type="checkbox"> Maintenance mode</label><label><input id="demoEnabled" type="checkbox"> Show demo link</label><label><input id="featured" type="checkbox"> Featured first</label></div>
</div><div class="form-actions"><button type="button" class="button secondary" id="cancel">Cancel</button><button class="button" id="save" type="submit">Save product</button></div><div class="status" id="formStatus"></div></form></div></div></div>
<script>
const $=id=>document.getElementById(id);let records=[],editing=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function adminCsrf(){return decodeURIComponent(document.cookie.split(';').map(x=>x.trim()).find(x=>x.startsWith('hex_admin_csrf='))?.slice('hex_admin_csrf='.length)||'')}
async function api(path,options={}){const headers={...(options.headers||{})};if(!['GET','HEAD','OPTIONS'].includes(String(options.method||'GET').toUpperCase()))headers['X-Admin-CSRF']=adminCsrf();const r=await fetch(path,{...options,headers,credentials:'same-origin'});if(r.status===401){location.href='/admin';throw Error('Admin session expired. Sign in again.')}let body;try{body=await r.json()}catch{body={error:await r.text()}}if(!r.ok)throw Error(body.error||body.message||'Request failed');return body}
function parseMap(text){const out={};for(const line of text.split(/\r?\n/)){if(!line.trim())continue;const n=line.indexOf('=');if(n<1)throw Error('Use one “duration = value” per line.');out[line.slice(0,n).trim()]=line.slice(n+1).trim()}return out}
function mapText(obj){return Object.entries(obj||{}).map(([k,v])=>`${k} = ${String(v).replace(/[₹$]/g,'')}`).join('\n')}
function render(){if(!records.length){$('products').innerHTML='<div class="empty">No products in the catalog.</div>';return}$('products').innerHTML=records.map(p=>`<article class="card"><div class="thumb">${p.image_url?`<img src="${esc(p.image_url)}?v=${Date.now()}" onerror="this.remove()" alt="${esc(p.name)}">`:'HX'}</div><div class="body"><div class="title"><h2>${esc(p.name)}</h2><span class="pill">${p.enabled?'Visible':'Hidden'}${p.maintenance?' · Maintenance':''}</span></div><div class="meta">${esc(p.key)} · reseller ID ${esc(p.id)}<br>${esc(p.platform||'Platform not set')} · ${esc(p.access_mode==='root'?'Root':p.access_mode==='non_root'?'Non-root':'Root + non-root')}</div><div class="prices">${(p.durations||[]).map(d=>`${esc(d)}: <b>${esc(p.prices?.[d]||'—')}</b>`).join('<br>')}</div><div class="row"><button class="button secondary" onclick="edit('${esc(p.key)}')">Edit</button><button class="button secondary" onclick="imageFor('${esc(p.key)}')">Upload image</button><button class="button danger" onclick="removeProduct('${esc(p.key)}')">${p.is_builtin?'Disable':'Delete'}</button></div></div></article>`).join('')}
async function load(){try{const d=await api('/admin/api/products');records=d.products||[];render()}catch(e){$('products').innerHTML=`<div class="empty">${esc(e.message)}. Sign in at <a href="/admin">/admin</a> first.</div>`}}
function openForm(p=null){editing=p?.key||null;$('modalTitle').textContent=p?'Edit product':'Add product';$('key').value=p?.key||'';$('key').readOnly=!!p;$('productId').value=p?.id||'';$('name').value=p?.name||'';$('category').value=p?.category||'';$('platform').value=p?.platform||'';$('accessMode').value=p?.access_mode||'all';$('description').value=p?.description||'';$('durations').value=(p?.durations||[]).join('\n');$('prices').value=mapText(p?.prices);$('usdPrices').value=mapText(p?.usd_prices);$('apiDurations').value=mapText(p?.api_duration);$('stock').value=mapText(p?.stock);$('features').value=(p?.features||[]).map(f=>Array.isArray(f)?f[0]:f).join('\n');$('demoUrl').value=p?.demo_url||'';$('downloadUrl').value=p?.download_url||'';$('sortOrder').value=p?.sort_order||0;$('soldCount').value=p?.sold_count||0;$('enabled').checked=p?.enabled!==false;$('maintenance').checked=!!p?.maintenance;$('demoEnabled').checked=!!p?.demo_enabled;$('featured').checked=!!p?.featured;$('image').value='';$('formStatus').textContent='';$('formStatus').className='status';$('modal').classList.remove('hidden')}
function edit(key){const p=records.find(x=>x.key===key);if(p)openForm(p)}
async function imageFor(key){const p=records.find(x=>x.key===key);openForm(p);$('image').focus()}
function closeForm(){$('modal').classList.add('hidden')}
async function save(event){event.preventDefault();$('formStatus').textContent='';$('save').disabled=true;try{const durations=$('durations').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(!durations.length||durations.length>30)throw Error('Enter between 1 and 30 durations.');const prices=parseMap($('prices').value);if(durations.some(d=>!prices[d]||!Number.isFinite(Number(prices[d].replace(/[₹$,]/g,'')))))throw Error('Enter a valid INR price for every duration.');const usdText=$('usdPrices').value.trim();const usd=usdText?parseMap(usdText):{};const payload={product:{id:$('productId').value.trim(),name:$('name').value.trim(),category:$('category').value.trim(),platform:$('platform').value,access_mode:$('accessMode').value,description:$('description').value.trim(),download_url:$('downloadUrl').value.trim(),sort_order:Number($('sortOrder').value||0),sold_count:Number($('soldCount').value||0),featured:$('featured').checked,durations,prices,usd_prices:usd,api_duration:parseMap($('apiDurations').value),stock:parseMap($('stock').value),feature_names:$('features').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean),enabled:$('enabled').checked,maintenance:$('maintenance').checked,demo_url:$('demoUrl').value.trim(),demo_enabled:$('demoEnabled').checked}};let result;if(editing){result=await api('/admin/api/products/'+encodeURIComponent(editing),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)})}else{payload.key=$('key').value.trim();result=await api('/admin/api/products',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)})}const file=$('image').files?.[0];if(file)await uploadImage(result.product?.key||editing||payload.key,file);closeForm();await load();$('status').textContent='Product saved.'}catch(e){$('formStatus').textContent=e.message;$('formStatus').className='status error'}finally{$('save').disabled=false}}
async function uploadImage(key,file){if(file.size>5*1024*1024)throw Error('Image must be 5 MB or smaller.');const data=new FormData();data.append('image',file,file.name);await api('/admin/api/products/'+encodeURIComponent(key)+'/image',{method:'POST',body:data})}
async function removeProduct(key){const p=records.find(x=>x.key===key);if(!p)return;const label=p.is_builtin?'Disable '+p.name+'? This keeps the built-in product definition but hides it from the storefront.':'Delete '+p.name+' from the catalog?';if(!confirm(label))return;try{await api('/admin/api/products/'+encodeURIComponent(key),{method:'DELETE'});await load();$('status').textContent='Catalog updated.'}catch(e){$('status').textContent=e.message;$('status').className='status error'}}
$('add').addEventListener('click',()=>openForm());$('close').addEventListener('click',closeForm);$('cancel').addEventListener('click',closeForm);$('form').addEventListener('submit',save);$('logout').addEventListener('click',async()=>{try{await api('/admin/api/logout',{method:'POST'})}finally{location.href='/admin'}});$('modal').addEventListener('click',e=>{if(e.target===$('modal'))closeForm()});load();
</script></body></html>
